// Characterization tests: pin the current client-visible behavior of the HTTP API,
// including quirks, so a restructuring can't change them unnoticed.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 2.5, C: 60, D: 0.3 }
const pricing = { priceOf: async (sku) => prices[sku] }

let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: raw ?? JSON.stringify(body),
})

test('POST /orders creates an order and returns 201 JSON', async () => {
  const res = await post({ items: [{ sku: 'A', qty: 2 }] })
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  const order = await res.json()
  assert.deepEqual(Object.keys(order).sort(), ['id', 'items', 'total'])
  assert.equal(typeof order.id, 'string')
  assert.deepEqual(order.items, [{ sku: 'A', qty: 2 }])
  assert.equal(order.total, 20)
})

test('ids are sequential strings', async () => {
  const a = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('total sums multiple items', async () => {
  const order = await (await post({ items: [{ sku: 'A', qty: 1 }, { sku: 'C', qty: 1 }] })).json()
  assert.equal(order.total, 70)
})

test('total is floored to a whole number', async () => {
  const order = await (await post({ items: [{ sku: 'B', qty: 3 }] })).json() // 7.5
  assert.equal(order.total, 7)
  const small = await (await post({ items: [{ sku: 'D', qty: 1 }] })).json() // 0.3
  assert.equal(small.total, 0)
})

test('10% discount applies only when raw total is over 100', async () => {
  const exactly100 = await (await post({ items: [{ sku: 'A', qty: 10 }] })).json()
  assert.equal(exactly100.total, 100)
  const over = await (await post({ items: [{ sku: 'A', qty: 11 }] })).json() // 110 -> 99
  assert.equal(over.total, 99)
  const floored = await (await post({ items: [{ sku: 'C', qty: 2 }, { sku: 'B', qty: 1 }] })).json() // 122.5 -> 110.25
  assert.equal(floored.total, 110)
})

test('POST /orders rejects missing, empty or non-array items with 400', async () => {
  for (const body of [{}, { items: [] }, { items: 'x' }, { items: null }]) {
    const res = await post(body)
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('POST /orders rejects invalid JSON with 400', async () => {
  const res = await post(undefined, '{not json')
  assert.equal(res.status, 400)
  assert.deepEqual(await res.json(), { error: 'items required' })
})

test('POST /orders with empty body is 400', async () => {
  const res = await post(undefined, '')
  assert.equal(res.status, 400)
  assert.deepEqual(await res.json(), { error: 'items required' })
})

test('GET /orders/:id returns a created order', async () => {
  const created = await (await post({ items: [{ sku: 'A', qty: 3 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(await res.json(), created)
})

test('GET /orders/:id for unknown id returns 200 with an error body (not 404)', async () => {
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown routes and methods return 404 "no route"', async () => {
  const cases = [
    ['GET', '/'],
    ['GET', '/orders'],
    ['GET', '/orders/1/extra'],
    ['PUT', '/orders'],
    ['DELETE', '/orders/1'],
    ['POST', '/orders/1'],
  ]
  for (const [method, path] of cases) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})

test('query string is ignored when routing', async () => {
  const res = await post({ items: [{ sku: 'A', qty: 1 }] })
  const { id } = await res.json()
  const got = await fetch(`${base}/orders/${id}?x=1`)
  assert.equal((await got.json()).id, id)
})
